<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { useRoute } from 'vue-router'
import { actualizarAccionFlujo, crearAccionFlujo, eliminarAccionFlujo, listarAccionesFlujo } from '../services/accionesFlujo'
import type { AccionFlujo, Option } from '../interfaces/accionesFlujo.interface'
const route=useRoute(),rows=ref<AccionFlujo[]>([]),flujos=ref<Option[]>([]),trabajos=ref<Option[]>([]),acciones=ref<Option[]>([]),editing=ref<AccionFlujo|null>(null),modal=ref(false),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref('')
const filters=reactive({flujo_id:String(route.query.flujo||''),criterio:'',page:1}),form=reactive({flujo_id:'',tipo_trabajo_id:'',condicion:'',accion_si_id:'',accion_no_id:'',secuencia:1,activo:true})
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarAccionesFlujo(filters);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;flujos.value=r.flujos;trabajos.value=r.tipos_trabajo;acciones.value=r.acciones}catch(e){error.value=msg(e)}finally{loading.value=false}}
function open(x?:AccionFlujo){editing.value=x||null;Object.assign(form,{flujo_id:String(x?.flujo_id||filters.flujo_id||''),tipo_trabajo_id:String(x?.tipo_trabajo_id||''),condicion:x?.condicion||'',accion_si_id:String(x?.accion_si_id||''),accion_no_id:String(x?.accion_no_id||''),secuencia:x?.secuencia||rows.value.length+1,activo:x?.activo??true});modal.value=true}
async function submit(){if(!form.flujo_id||!form.tipo_trabajo_id||!form.condicion.trim()||!form.accion_si_id||!form.accion_no_id){error.value='Complete todos los datos de la acción del flujo.';return}saving.value=true;error.value='';try{editing.value?await actualizarAccionFlujo(editing.value.id,form):await crearAccionFlujo(form);success.value='Acción del flujo guardada correctamente.';modal.value=false;await load(filters.page)}catch(e){error.value=msg(e)}finally{saving.value=false}}
async function remove(x:AccionFlujo){if(!confirm(`¿Eliminar el paso ${x.secuencia} del flujo?`))return;try{await eliminarAccionFlujo(x.id);success.value='Paso retirado del flujo.';await load(filters.page)}catch(e){error.value=msg(e)}}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Comercialización / Acciones del flujo</nav><header class="hero"><div class="mark">↗</div><div><small>EVAN · CONFIGURACIÓN COMERCIAL</small><h1>Acciones del flujo</h1><p>Secuencia, condiciones y decisiones de cada procedimiento.</p></div><strong>{{total}} pasos</strong><button @click="open()">+ Nueva acción</button></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><label>Flujo de atención<select v-model="filters.flujo_id" @change="load(1)"><option value="">Todos</option><option v-for="x in flujos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Buscar<input v-model.trim="filters.criterio" placeholder="Condición o tipo de trabajo" @keyup.enter="load(1)"></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando acciones del flujo…</div><div v-else-if="!rows.length" class="empty">No existen pasos configurados para la selección.</div><section v-else class="flow"><article v-for="x in rows" :key="x.id"><div class="seq">{{x.secuencia}}</div><div class="work"><small>{{x.flujo}}</small><h2>{{x.tipo_trabajo}}</h2><p>{{x.condicion}}</p></div><div class="branch yes"><small>SI</small><b>{{x.accion_si}}</b></div><div class="branch no"><small>NO</small><b>{{x.accion_no}}</b></div><em :class="{off:!x.activo}">{{x.activo?'Activo':'Inactivo'}}</em><div class="actions"><button @click="open(x)">Editar</button><button @click="remove(x)">Retirar</button></div></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="submit"><header><div><small>ACCIÓN DEL FLUJO</small><h2>{{editing?'Modificar paso':'Registrar nuevo paso'}}</h2><p>Configure el trabajo y las rutas que se ejecutarán según la condición.</p></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Flujo de atención *<select v-model="form.flujo_id" required><option value="">Seleccione</option><option v-for="x in flujos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Tipo de trabajo *<select v-model="form.tipo_trabajo_id" required><option value="">Seleccione</option><option v-for="x in trabajos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label></div><label>Condición *<input v-model.trim="form.condicion" maxlength="255" placeholder="Ejemplo: ¿Cumple los requisitos?" required></label><div class="grid"><label>Acción si cumple *<select v-model="form.accion_si_id" required><option value="">Seleccione</option><option v-for="x in acciones" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Acción si no cumple *<select v-model="form.accion_no_id" required><option value="">Seleccione</option><option v-for="x in acciones" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Secuencia *<input v-model.number="form.secuencia" type="number" min="1" required></label><label class="check"><input v-model="form.activo" type="checkbox"> Paso activo</label></div><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar paso'}}</button></footer></form></div></div></template>
<style scoped>
