-size:.48rem}.actions button:last-child{color:#b44f55}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.6rem}.pages{display:flex;justify-content:center;align-items:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,760px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin:11px 0;font-size:.55rem}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.check{display:flex!important;align-items:center;gap:7px}.check input{width:auto}.modal footer{display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}@media(max-width:900px){.flow{overflow:auto}.flow article{min-width:780px}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:520px){.grid{grid-template-columns:1fr}}
</style>
